1	/**
2	 * @module features/tv-dashboard/ui/TvColumnParts
3	 *
4	 * Blocos compartilhados das COLUNAS VERTICAIS da v3 (spec v3 — visão geral
5	 * `/tv`): chassi clicável com RAG, linha de última bipagem, perdas do
6	 * período, estoque crítico NOMEADO e mini-feed "AGORA". Usados por
7	 * `TvStoreColumn` (lojas) e `TvFabricaColumn` (fábrica).
8	 *
9	 * A coluna INTEIRA navega para `/tv/loja/:id` (acessível: role link +
10	 * Enter/Espaço). Cores fora da paleta sage só em desvio (âmbar/vermelho),
11	 * sempre com redundância ícone+texto.
12	 */
13	
14	import type { KeyboardEvent, ReactNode } from 'react';
15	import { useNavigate } from 'react-router-dom';
16	import {
17	  ArrowDownRight,
18	  ArrowUpRight,
19	  CheckCircle2,
20	  OctagonAlert,
21	  ScanLine,
22	  TriangleAlert,
23	} from 'lucide-react';
24	import type {
25	  TvCriticalItem,
26	  TvPerdasSummary,
27	  TvPeriod,
28	  TvRagStatus,
29	  TvRecentMove,
30	} from '../model/types';
31	import {
32	  TV_CRITICAL_TOP_N,
33	  TV_MINI_FEED_SIZE,
34	  formatCompactBRL,
35	} from '../model/tvMath';
36	import { TV_PERIOD_LABEL, formatAgoLabel, formatQty, formatTimeHHMM } from './tvFormat';
37	
38	/** Borda + glow por estado RAG (sinal lível a 5m — mesma régua da v2). */
39	const COLUMN_RAG_FRAME: Record<TvRagStatus, string> = {
40	  ok: 'border border-[#57715B]/10 shadow-[0_8px_32px_rgba(0,0,0,0.06)]',
41	  amber: 'border-2 border-amber-400/60 shadow-[0_8px_32px_rgba(245,158,11,0.18)]',
42	  red: 'border-2 border-red-400/70 shadow-[0_8px_32px_rgba(229,72,77,0.15)]',
43	};
44	
45	interface TvUnitColumnProps {
46	  lojaId: number;
47	  nome: string;
48	  rag: TvRagStatus;
49	  /** Hairline dourado de assinatura (fábrica). */
50	  goldHairline?: boolean;
51	  testId: string;
52	  children: ReactNode;
53	}
54	
55	/**
56	 * Chassi da coluna vertical: glass premium + frame RAG + clique/teclado
57	 * navegando para o drill-down `/tv/loja/:id`.
58	 */
59	export function TvUnitColumn({
60	  lojaId,
61	  nome,
62	  rag,
63	  goldHairline = false,
64	  testId,
65	  children,
66	}: TvUnitColumnProps) {
67	  const navigate = useNavigate();
68	  const open = () => navigate(`/tv/loja/${lojaId}`);
69	  const onKeyDown = (e: KeyboardEvent<HTMLElement>) => {
70	    if (e.key === 'Enter' || e.key === ' ') {
71	      e.preventDefault();
72	      open();
73	    }
74	  };
75	
76	  return (
77	    <section
78	      role="link"
79	      tabIndex={0}
80	      aria-label={`Abrir detalhes de ${nome}`}
81	      data-mia-action={`abrir-detalhe-loja-${lojaId}`}
82	      onClick={open}
83	      onKeyDown={onKeyDown}
84	      className={`relative flex cursor-pointer flex-col overflow-hidden rounded-[2rem] bg-white/60 p-3.5 backdrop-blur-xl saturate-150 transition-[border-color,box-shadow,background-color] [transition-duration:300ms] hover:bg-white/80 hover:shadow-[0_12px_40px_rgba(0,0,0,0.10)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#57715B]/40 motion-reduce:transition-none lg:p-4 ${COLUMN_RAG_FRAME[rag]}`}
85	      data-testid={testId}
86	      data-rag={rag}
87	    >
88	      {/* Gradiente interno sutil (assinatura glass premium) */}
89	      <div
90	        className="pointer-events-none absolute inset-0 bg-gradient-to-br from-white/40 via-transparent to-[#C5A065]/5"
91	        aria-hidden
92	      />
93	      {goldHairline && (
94	        <div className="absolute inset-x-0 top-0 h-0.5 bg-[#C5A065]/60" aria-hidden />
95	      )}
96	      <div className="relative z-10 flex h-full min-h-0 flex-col">{children}</div>
97	    </section>
98	  );
99	}
100	
101	/** Rótulo micro de seção dentro da coluna ("PERDAS · HOJE", "AGORA"…). */
102	export function TvColumnLabel({ children }: { children: ReactNode }) {
103	  return (
104	    <p className="font-momma text-[clamp(0.6875rem,0.75vw,1.375rem)] font-semibold uppercase tracking-wider text-[#5F6F63]">
105	      {children}
106	    </p>
107	  );
108	}
109	
110	/**
111	 * Linha de "pulso" da unidade: última bipagem com hora + "há X min".
112	 * Sem bipagem hoje → texto explícito (nunca campo em branco).
113	 */
114	export function TvColumnBipLine({
115	  ultimaBipagem,
116	  now,
117	}: {
118	  ultimaBipagem: string | null;
119	  now: Date;
120	}) {
121	  const time = formatTimeHHMM(ultimaBipagem);
122	  const ago = formatAgoLabel(ultimaBipagem, now);
123	  return (
124	    <p
125	      className="mt-0.5 flex items-center gap-1.5 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] font-medium leading-tight text-[#7C887E]"
126	      data-testid="tv-col-bip"
127	    >
128	      <ScanLine className="h-[1em] w-[1em] shrink-0" aria-hidden />
129	      {time ? `bip ${time}${ago ? ` · ${ago}` : ''}` : 'sem bipagem hoje'}
130	    </p>
131	  );
132	}
133	
134	/** Perdas da unidade no período do filtro global (R$ + nº de itens). */
135	export function TvColumnPerdas({
136	  perdas,
137	  period,
138	}: {
139	  perdas: TvPerdasSummary;
140	  period: TvPeriod;
141	}) {
142	  return (
143	    <div className="mt-3" data-testid="tv-col-perdas">
144	      <TvColumnLabel>PERDAS · {TV_PERIOD_LABEL[period]}</TvColumnLabel>
145	      <p className="mt-0.5 font-momma text-[clamp(0.9375rem,1.1vw,2rem)] font-semibold leading-none text-[#2D362E] tabular-nums">
146	        {formatCompactBRL(perdas.valor)}
147	        <span className="font-normal text-[#7C887E]">
148	          {' '}
149	          · {perdas.itens} {perdas.itens === 1 ? 'item' : 'itens'}
150	        </span>
151	      </p>
152	    </div>
153	  );
154	}
155	
156	/**
157	 * Estoque crítico NOMEADO (top {@link TV_CRITICAL_TOP_N} por severidade):
158	 * ⛔ zerado (vermelho) / ⚠ abaixo do mínimo (âmbar) com "X de Y mín".
159	 * Vazio → "✓ estoque ok" explícito.
160	 */
161	export function TvColumnCritical({ items }: { items: TvCriticalItem[] }) {
162	  const visible = items.slice(0, TV_CRITICAL_TOP_N);
163	  const overflow = items.length - visible.length;
164	  return (
165	    <div className="mt-3 flex min-h-0 flex-1 flex-col" data-testid="tv-col-critical">
166	      <TvColumnLabel>ESTOQUE CRÍTICO</TvColumnLabel>
167	      {items.length === 0 ? (
168	        <p
169	          className="mt-1 flex items-center gap-1.5 font-momma text-[clamp(0.75rem,0.85vw,1.5rem)] font-medium text-emerald-600"
170	          data-testid="tv-col-critical-empty"
171	        >
172	          <CheckCircle2 className="h-[1em] w-[1em] shrink-0" aria-hidden />
173	          estoque ok
174	        </p>
175	      ) : (
176	        <ul className="mt-1 space-y-1">
177	          {visible.map((item) => {
178	            const zerado = item.severity === 'zerado';
179	            return (
180	              <li
181	                key={item.nome}
182	                className="flex items-center gap-1.5 font-momma text-[clamp(0.75rem,0.85vw,1.5rem)] leading-tight"
183	                data-testid="tv-col-critical-item"
184	                data-severity={item.severity}
185	              >
186	                {zerado ? (
187	                  <OctagonAlert
188	                    className="h-[1em] w-[1em] shrink-0 text-red-500"
189	                    aria-hidden
190	                  />
191	                ) : (
192	                  <TriangleAlert
193	                    className="h-[1em] w-[1em] shrink-0 text-amber-500"
194	                    aria-hidden
195	                  />
196	                )}
197	                <span className="min-w-0 flex-1 truncate font-medium text-[#2D362E]">
198	                  {item.nome}
199	                </span>
200	                <span
201	                  className={`shrink-0 font-medium tabular-nums ${
202	                    zerado ? 'text-red-600' : 'text-amber-600'
203	                  }`}
204	                >
205	                  {zerado
206	                    ? '0 un'
207	                    : `${formatQty(item.quantidade)} de ${formatQty(item.minima)} mín`}
208	                </span>
209	              </li>
210	            );
211	          })}
212	          {overflow > 0 && (
213	            <li
214	              className="font-momma text-[clamp(0.6875rem,0.75vw,1.375rem)] text-[#7C887E]"
215	              data-testid="tv-col-critical-overflow"
216	            >
217	              + {overflow} {overflow === 1 ? 'item' : 'itens'}
218	            </li>
219	          )}
220	        </ul>
221	      )}
222	    </div>
223	  );
224	}
225	
226	/**
227	 * Mini-feed "AGORA": últimas {@link TV_MINI_FEED_SIZE} movimentações de
228	 * hoje (HH:MM ↗/↘ qtd× produto). Vazio → texto explícito.
229	 */
230	export function TvColumnFeed({ moves }: { moves: TvRecentMove[] }) {
231	  const visible = moves.slice(0, TV_MINI_FEED_SIZE);
232	  return (
233	    <div className="mt-3" data-testid="tv-col-feed">
234	      <TvColumnLabel>AGORA</TvColumnLabel>
235	      {visible.length === 0 ? (
236	        <p
237	          className="mt-1 font-momma text-[clamp(0.75rem,0.85vw,1.5rem)] text-[#7C887E]"
238	          data-testid="tv-col-feed-empty"
239	        >
240	          sem movimentações hoje
241	        </p>
242	      ) : (
243	        <ul className="mt-1 space-y-1">
244	          {visible.map((m, i) => (
245	            <li
246	              key={`${m.timestamp ?? 'sem-ts'}-${m.produtoNome}-${i}`}
247	              className="flex items-center gap-1.5 font-momma text-[clamp(0.75rem,0.85vw,1.5rem)] leading-tight"
248	              data-testid="tv-col-feed-item"
249	            >
250	              <span className="shrink-0 font-medium text-[#7C887E] tabular-nums">
251	                {m.hora}
252	              </span>
253	              {m.tipo === 'entrada' ? (
254	                <ArrowUpRight
255	                  className="h-[1em] w-[1em] shrink-0 text-[#57715B]"
256	                  aria-hidden
257	                />
258	              ) : (
259	                <ArrowDownRight
260	                  className="h-[1em] w-[1em] shrink-0 text-[#7C887E]"
261	                  aria-hidden
262	                />
263	              )}
264	              <span className="min-w-0 flex-1 truncate text-[#2D362E]">
265	                {formatQty(m.quantidade)}× {m.produtoNome}
266	              </span>
267	            </li>
268	          ))}
269	        </ul>
270	      )}
271	    </div>
272	  );
273	}
