1	/**
2	 * @module features/tv-dashboard/ui/TvStoreColumn
3	 *
4	 * Coluna VERTICAL de loja da v3 (substitui o card horizontal da v2).
5	 * De cima para baixo: header (nome + chip RAG + fonte) · última bipagem ·
6	 * vendas de hoje + % vs ontem (pró-rata p/ canal live; Linx com selo
7	 * honesto "até DD/MM") · perdas do período do filtro global · estoque
8	 * crítico NOMEADO (top 5) · mini-feed "AGORA". A coluna inteira é clicável
9	 * e navega para `/tv/loja/:id`.
10	 */
11	
12	import type { TvFreshnessLevel, TvPeriod, TvStoreData } from '../model/types';
