34	/** Coluna de loja: cobre canal Degust live e Linx defasado. */
35	export function TvStoreColumn({ store, liveLevel, period, now }: TvStoreColumnProps) {
36	  const { vendas, channel } = store;
37	  const isLive = channel === 'degust-live';
38	  const valorAnim = useCountUp(vendas?.valor ?? 0);
39	  const refDate = vendas ? parseIsoDateLocal(vendas.dataReferencia) : null;
40	
41	  // Caption sob as vendas: honestidade da fonte (live × defasado × sem dado)
42	  let caption: string;
43	  if (vendas == null) {
44	    caption = 'sem dado de venda disponível';
45	  } else if (isLive) {
46	    // `ultima_atualizacao` do Degust vem "DD/MM/YYYY HH:mm:ss" — parser
47	    // dedicado pt-BR (new Date() falha para dia > 12).
48	    const upd = formatTimeHHMM(parseBrDateTime(vendas.atualizadoEm));
49	    caption = `hoje${upd ? ` · atualizado ${upd}` : ''}`;
50	  } else {
51	    caption = `${refDate ? formatWeekdayDayMonth(refDate) : ''} — último dia com dados`;
52	  }
53	
54	  return (
55	    <TvUnitColumn
56	      lojaId={store.lojaId}
57	      nome={store.nome}
58	      rag={store.rag}
59	      testId="tv-store-column"
60	    >
61	      {/* Header: nome + chips (RAG + fonte) */}
62	      <div className="flex flex-wrap items-center justify-between gap-x-2 gap-y-1">
63	        <h2 className="min-w-0 truncate font-momma text-[clamp(0.9375rem,1.05vw,1.875rem)] font-semibold leading-tight text-[#2D362E]">
64	          {store.nome}
65	        </h2>
66	        <div className="flex shrink-0 flex-wrap items-center justify-end gap-1.5">
67	          <TvStateChip rag={store.rag} />
68	          <TvSourceChip
69	            channel={channel}
70	            liveLevel={liveLevel}
71	            laggedDate={vendas?.dataReferencia ?? null}
72	          />
73	        </div>
74	      </div>
75	      <TvColumnBipLine ultimaBipagem={store.movimentacao.ultimaBipagem} now={now} />
76	
77	      {/* Vendas de hoje + % vs ontem (principal v3) */}
78	      <div className="mt-2 flex flex-wrap items-end gap-x-2 gap-y-1">
79	        <span
80	          className={`font-momma text-[clamp(1.75rem,1.95vw,3.5rem)] font-bold leading-none tabular-nums ${
81	            vendas ? 'text-[#2D362E]' : 'text-[#7C887E]'
82	          }`}
83	          data-testid="tv-store-sales"
84	        >
85	          {vendas ? formatCompactBRL(valorAnim) : '—'}
86	        </span>
87	        {store.deltaOntem != null && (
88	          <TvDeltaChip
89	            delta={store.deltaOntem}
90	            label={isLive ? 'ontem' : 'dia ant.'}
91	            size="card"
92	          />
93	        )}
94	      </div>
95	      <p className="mt-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] font-medium leading-tight text-[#7C887E]">
96	        {caption}
97	      </p>
98	
99	      <TvColumnPerdas perdas={store.perdas} period={period} />
100	      <TvColumnCritical items={store.criticalItems} />
101	      <TvColumnFeed moves={store.recentMoves} />
102	    </TvUnitColumn>
103	  );
104	}
