82	/** Página raiz do painel TV. */
83	export default function TvDashboardPage() {
84	  const navigate = useNavigate();
85	  // Filtro global v3: muda perdas/compras/comparativos (vendas seguem hoje)
86	  const [period, setPeriod] = useState<TvPeriod>('today');
87	  const data = useTvDashboardData(period);
88	  useTvRealtime();
89	  const now = useMinuteClock();
90	
91	  // Telas touch (sem hover) não disparam mousemove confiável — o botão
92	  // Metas fica SEMPRE visível, discreto no canto (design.md §8.4).
93	  const [isTouch] = useState(
94	    () =>
95	      typeof window !== 'undefined' &&
96	      typeof window.matchMedia === 'function' &&
97	      window.matchMedia('(hover: none)').matches,
98	  );
99	
100	  // Botão fantasma "Metas": invisível por padrão; mousemove revela por 5s
101	  // e suspende o cursor-none enquanto visível (design.md §8.4).
102	  const [controlsVisible, setControlsVisible] = useState(false);
103	  const hideTimer = useRef<number | null>(null);
104	  useEffect(() => {
105	    const onMove = () => {
106	      setControlsVisible(true);
107	      if (hideTimer.current != null) window.clearTimeout(hideTimer.current);
108	      hideTimer.current = window.setTimeout(
109	        () => setControlsVisible(false),
110	        METAS_BUTTON_VISIBLE_MS,
111	      );
112	    };
113	    window.addEventListener('mousemove', onMove);
114	    return () => {
115	      window.removeEventListener('mousemove', onMove);
116	      if (hideTimer.current != null) window.clearTimeout(hideTimer.current);
117	    };
118	  }, []);
119	
120	  // ── Loading inicial (§7): wordmark + frase + 3 pontos em sequência ──
121	  if (data.isLoading) {
122	    return (
123	      <div className="relative flex min-h-dvh select-none flex-col items-center justify-center gap-5 bg-white font-momma antialiased">
124	        <TvAmbience />
125	        <span className="relative text-[clamp(1.5rem,2.1vw,3.75rem)] font-bold uppercase tracking-[0.3em] text-[#C5A065]">
126	          MOMMA
127	        </span>
128	        <span className="relative text-[clamp(1rem,1.25vw,2.25rem)] text-[#5F6F63]">
129	          carregando painel…
130	        </span>
131	        <div
132	          className="relative flex gap-2 text-[clamp(1rem,1.25vw,2.25rem)] text-[#7C887E]"
133	          aria-hidden
134	        >
135	          <span className="tv-dot">·</span>
136	          <span className="tv-dot">·</span>
137	          <span className="tv-dot">·</span>
138	        </div>
139	      </div>
140	    );
141	  }
142	
143	  const storeCards = data.stores.slice(0, data.factory ? 5 : 6);
144	
145	  // Em touch o botão Metas é permanente; com mouse, segue o ghost de 5s.
146	  const metasVisible = isTouch || controlsVisible;
147	
148	  return (
149	    <div
150	      className={`tv-lock-viewport relative min-h-dvh select-none overflow-x-hidden bg-white font-momma text-[#2D362E] antialiased ${
151	        metasVisible ? '' : 'cursor-none'
152	      }`}
153	      data-testid="tv-dashboard"
154	    >
155	      <TvAmbience />
156	
157	      <div className="tv-pixel-shift tv-lock-fill relative">
158	        <div className="tv-content-enter tv-lock-fill flex flex-col gap-4 p-4 sm:p-6 lg:gap-5 lg:px-8 lg:py-6">
159	          {/* Linha 1 — hero (com filtro global Hoje/Semana/Mês) */}
160	          <TvHero
161	            network={data.network}
162	            freshness={data.freshness}
163	            now={now}
164	            period={period}
165	            onPeriodChange={setPeriod}
166	          />
167	
168	          {/* Linha 2 — colunas verticais de unidade (fábrica na posição 6):
169	              1 col no mobile → 2 (sm) → 3 (lg) → 6 lado a lado em xl+/TV;
170	              no viewport-lock absorvem a altura restante (tv-lock-grow). */}
171	          <div className="tv-lock-grow grid auto-rows-fr grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 lg:gap-5 xl:grid-cols-6 xl:gap-4">
172	            {data.isError ? (
173	              <>
174	                {Array.from({ length: 6 }, (_, i) => (
175	                  <TvErrorCard key={i} />
176	                ))}
177	              </>
178	            ) : (
179	              <>
180	                {storeCards.map((store) => (
181	                  <TvStoreColumn
182	                    key={store.lojaId}
183	                    store={store}
184	                    liveLevel={data.freshness.vendasLive.level}
185	                    period={period}
186	                    now={now}
187	                  />
188	                ))}
189	                {data.factory && (
190	                  <TvFabricaColumn
191	                    factory={data.factory}
192	                    freshness={data.freshness}
193	                    period={period}
194	                    now={now}
195	                  />
196	                )}
197	              </>
198	            )}
199	          </div>
200	        </div>
201	      </div>
202	
203	      {/* Botão de Metas (§8.4): fantasma com mouse, permanente em touch */}
204	      <button
205	        type="button"
206	        onClick={() => navigate('/tv/metas')}
207	        data-mia-action="abrir-metas-painel-tv"
208	        className={`fixed bottom-4 right-4 flex h-11 items-center gap-2 rounded-full border border-[#57715B]/15 bg-white/80 px-5 font-momma text-[clamp(0.875rem,1.05vw,1.25rem)] font-medium text-[#57715B] shadow-[0_4px_16px_rgba(0,0,0,0.08)] backdrop-blur-md transition-opacity duration-200 motion-reduce:transition-none lg:bottom-6 lg:right-8 ${
209	          metasVisible ? 'opacity-100' : 'pointer-events-none opacity-0'
210	        }`}
211	        aria-hidden={!metasVisible}
212	        tabIndex={metasVisible ? 0 : -1}
213	      >
214	        <Settings2 className="h-5 w-5" aria-hidden />
215	        Metas
216	      </button>
217	    </div>
218	  );
