1	/**
2	 * @module features/tv-dashboard/ui/tvFormat
3	 *
4	 * Formatadores de APRESENTAÇÃO do Painel TV (camada UI).
5	 * Regras de negócio/agregação vivem em `../model/tvMath` — aqui só render.
6	 */
7	
8	import type { TvPeriod } from '../model/types';
9	import { businessDayFraction } from '../model/tvMath';
10	
11	/** Cor semântica da barra de meta (design.md §1.6 — estado de VENDA). */
12	export type TvBarColor = 'sage' | 'amber' | 'red';
13	
14	/** Rótulo pt-BR do filtro global de período (hero + colunas, v3). */
15	export const TV_PERIOD_LABEL: Record<TvPeriod, string> = {
16	  today: 'hoje',
17	  week: 'semana',
18	  month: 'mês',
19	};
20	
21	/** Abreviações pt-BR dos dias da semana (índice = `Date.getDay()`). */
22	export const WEEKDAY_ABBR = [
23	  'dom.',
24	  'seg.',
25	  'ter.',
26	  'qua.',
27	  'qui.',
28	  'sex.',
29	  'sáb.',
30	] as const;
31	
32	/** Hora local `HH:MM` (sem segundos — design.md §1.5), ou null sem dado. */
33	export function formatTimeHHMM(value: Date | string | null | undefined): string | null {
34	  if (value == null) return null;
35	  const d = value instanceof Date ? value : new Date(value);
36	  if (Number.isNaN(d.getTime())) return null;
37	  return d.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
38	}
39	
40	/** Contagem inteira com separador de milhar pt-BR ("1.240"). */
41	export function formatInt(value: number): string {
42	  return Math.round(value).toLocaleString('pt-BR');
43	}
44	
45	/**
46	 * Quantidade de estoque/movimentação: inteiro seco ("12") ou com até 1
47	 * decimal pt-BR quando fracionada ("2,5") — nunca arredonda silenciosamente
48	 * um fracionado para inteiro.
49	 */
50	export function formatQty(value: number): string {
51	  return value.toLocaleString('pt-BR', {
52	    minimumFractionDigits: 0,
53	    maximumFractionDigits: 1,
54	  });
55	}
56	
57	/** Ticket médio sempre com 2 decimais ("R$ 38,50" — design.md §1.5). */
58	export function formatTicketBRL(value: number): string {
59	  return `R$ ${value.toLocaleString('pt-BR', {
60	    minimumFractionDigits: 2,
61	    maximumFractionDigits: 2,
62	  })}`;
63	}
64	
65	/** Delta com sinal e seta textual implícita ("12%" — sinal vem do ícone). */
66	export function formatDeltaPct(delta: number): string {
67	  return `${Math.abs(Math.round(delta))}%`;
68	}
69	
70	/** Rótulo "ter. 03/06" para o dia de referência de canal defasado. */
71	export function formatWeekdayDayMonth(date: Date): string {
72	  const dd = String(date.getDate()).padStart(2, '0');
73	  const mm = String(date.getMonth() + 1).padStart(2, '0');
74	  return `${WEEKDAY_ABBR[date.getDay()]} ${dd}/${mm}`;
75	}
76	
77	/** "há 12 min" / "há 3h" para timestamps recentes; null sem dado. */
78	export function formatAgoLabel(
79	  value: Date | string | null | undefined,
80	  now: Date,
81	): string | null {
82	  if (value == null) return null;
83	  const d = value instanceof Date ? value : new Date(value);
84	  if (Number.isNaN(d.getTime())) return null;
85	  const diffMin = Math.max(0, Math.floor((now.getTime() - d.getTime()) / 60_000));
86	  if (diffMin < 60) return `há ${diffMin} min`;
87	  return `há ${Math.floor(diffMin / 60)}h`;
88	}
89	
90	/**
91	 * Cor da barra de % meta a partir do ratio pró-rata (`%real / %esperado`,
92	 * em fração: 1.0 = exatamente no ritmo). Regra do design.md §1.6:
93	 * sage ≥ 0,9 · âmbar 0,75–0,9 · vermelho abaixo de 0,6 após 12:00
94	 * (entre 0,6 e 0,75 fica âmbar).
95	 * Ratio nulo (sem meta / antes da janela) fica sage — barra neutra.
96	 */
97	export function metaBarColorFromRatio(ratio: number | null, now: Date): TvBarColor {
98	  if (ratio == null) return 'sage';
99	  if (ratio >= 0.9) return 'sage';
100	  if (ratio >= 0.75) return 'amber';
101	  if (ratio < 0.6 && now.getHours() >= 12) return 'red';
102	  return 'amber';
103	}
104	
105	/** % esperado AGORA da meta do dia (posição do tick pró-rata), 0–100. */
106	export function expectedPctNow(now: Date): number {
107	  return Math.round(businessDayFraction(now) * 100);
108	}
109	
110	/** Limita um percentual de preenchimento de barra ao intervalo [0, 100]. */
111	export function clampPct(pct: number | null): number {
112	  if (pct == null || Number.isNaN(pct)) return 0;
113	  return Math.max(0, Math.min(100, pct));
114	}
115

1	/**
2	 * @module features/tv-dashboard/ui/useCountUp
3	 *
4	 * Count-up de número do Painel TV (design.md §8.1.1): ao mudar de valor,
5	 * anima 400ms ease-out do valor antigo para o novo. Nunca em loop.
6	 * `prefers-reduced-motion: reduce` troca o valor seco (§8.1.7).
7	 */
8	
9	import { useEffect, useRef, useState } from 'react';
10	
11	/** Duração padrão do count-up (design.md §8.1.1). */
12	const COUNT_UP_MS = 400;
13	
14	function easeOut(t: number): number {
15	  return 1 - (1 - t) * (1 - t);
16	}
17	
18	function prefersReducedMotion(): boolean {
19	  return (
20	    typeof window !== 'undefined' &&
21	    typeof window.matchMedia === 'function' &&
22	    window.matchMedia('(prefers-reduced-motion: reduce)').matches
23	  );
24	}
25	
26	/**
27	 * Interpola `value` ao longo de 400ms quando ele muda (uma única vez por
28	 * mudança). No primeiro render retorna o valor direto (sem animar de 0).
29	 */
30	export function useCountUp(value: number, durationMs: number = COUNT_UP_MS): number {
31	  const [display, setDisplay] = useState(value);
32	  const fromRef = useRef(value);
33	  const rafRef = useRef<number | null>(null);
34	
35	  useEffect(() => {
36	    const from = fromRef.current;
37	    if (from === value) return;
38	    if (prefersReducedMotion() || typeof requestAnimationFrame !== 'function') {
39	      fromRef.current = value;
40	      setDisplay(value);
41	      return;
42	    }
43	    const start = performance.now();
44	    const step = (ts: number) => {
45	      const t = Math.min(1, (ts - start) / durationMs);
46	      const next = from + (value - from) * easeOut(t);
47	      setDisplay(next);
48	      if (t < 1) {
49	        rafRef.current = requestAnimationFrame(step);
50	      } else {
51	        fromRef.current = value;
52	        rafRef.current = null;
53	      }
54	    };
55	    rafRef.current = requestAnimationFrame(step);
56	    return () => {
57	      if (rafRef.current != null) cancelAnimationFrame(rafRef.current);
58	      fromRef.current = value;
59	    };
60	  }, [value, durationMs]);
61	
62	  return display;
63	}
64

