238	// ─────────────────────────────────────────────────────────────────────────────
239	// Pró-rata da meta
240	// ─────────────────────────────────────────────────────────────────────────────
241	
242	/**
243	 * Fração linear do dia comercial já decorrida em `now`.
244	 *
245	 * - Antes da abertura → 0 (não há venda esperada ainda).
246	 * - Depois do fechamento → 1 (meta integral esperada).
247	 * - Dentro da janela → interpolação linear simples (pró-rata).
248	 */
249	export function businessDayFraction(
250	  now: Date,
251	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
252	): number {
253	  const { start, end } = hours;
254	  if (end <= start) {
255	    // Janela inválida — fail fast com comportamento seguro (sem divisão por 0)
256	    return now.getHours() >= end ? 1 : 0;
257	  }
258	  const h = now.getHours() + now.getMinutes() / 60 + now.getSeconds() / 3600;
259	  if (h <= start) return 0;
260	  if (h >= end) return 1;
261	  return (h - start) / (end - start);
262	}
263	
264	/**
265	 * % da meta pró-rata: vendido / (meta diária × fração da janela decorrida).
266	 *
267	 * Retorna null quando não dá para calcular com honestidade:
268	 * - meta ausente/zerada (sem referência), ou
269	 * - antes da janela de funcionamento (esperado = 0; divisão sem sentido).
270	 */
271	export function pctOfProRataTarget(
272	  sold: number,
273	  dailyTarget: number | null | undefined,
274	  now: Date,
275	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
276	): number | null {
277	  if (dailyTarget == null || dailyTarget <= 0) return null;
278	  const fraction = businessDayFraction(now, hours);
279	  if (fraction <= 0) return null;
280	  return (sold / (dailyTarget * fraction)) * 100;
281	}
282	
283	/**
284	 * % da meta de um dia COMPLETO (sem pró-rata) — usado para canal defasado,
285	 * cujo dia de referência já encerrou.
286	 */
287	export function pctOfFullDayTarget(
288	  sold: number,
289	  dailyTarget: number | null | undefined,
290	): number | null {
291	  if (dailyTarget == null || dailyTarget <= 0) return null;
292	  return (sold / dailyTarget) * 100;
293	}
294	
295	// ─────────────────────────────────────────────────────────────────────────────
296	// Deltas comparativos (genéricos: vendas, perdas, compras — qualquer base)
297	// ─────────────────────────────────────────────────────────────────────────────
298	
299	/**
300	 * Delta % de `current` vs uma base de referência qualquer (ontem, semana
301	 * passada, período anterior do filtro…). Retorna null quando a base é
302	 * ausente ou não positiva — sem base honesta, sem número inventado.
303	 */
304	export function relativeDelta(
305	  current: number,
306	  base: number | null | undefined,
307	): number | null {
308	  if (base == null || base <= 0) return null;
309	  return ((current - base) / base) * 100;
310	}
311	
312	/**
313	 * Delta % vs MESMO DIA da semana anterior — caso particular de
314	 * {@link relativeDelta}, mantido pelo nome de domínio (comparativo
315	 * SECUNDÁRIO desde a v3; o principal é vs dia anterior).
316	 */
317	export function weekOverWeekDelta(
318	  current: number,
319	  lastWeek: number | null | undefined,
320	): number | null {
321	  return relativeDelta(current, lastWeek);
322	}
323	
324	/**
325	 * Base PRÓ-RATEADA de QUALQUER dia de referência para deltas do canal LIVE:
326	 * `referenceDayTotal × businessDayFraction(now)` — o delta resultante compara
327	 * hoje (dia parcial) vs o MESMO PONTO do dia de referência (ontem, semana
328	 * passada…), assumindo distribuição intra-dia linear na janela (mesma fração
329	 * usada no pró-rata da meta, por consistência).
330	 *
331	 * Comparar dia parcial com dia completo inflava a queda de manhã.
332	 * Canal defasado (dia completo vs dia completo) NÃO usa esta função.
333	 *
334	 * Retorna null quando a base é ausente/não positiva ou antes da abertura
335	 * (fração 0 — não há ponto de comparação honesto).
336	 */
337	export function proRataDayBase(
338	  referenceDayTotal: number | null | undefined,
339	  now: Date,
340	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
341	): number | null {
342	  if (referenceDayTotal == null || referenceDayTotal <= 0) return null;
343	  const fraction = businessDayFraction(now, hours);
344	  if (fraction <= 0) return null;
345	  return referenceDayTotal * fraction;
346	}
347	
348	/**
349	 * Alias histórico de {@link proRataDayBase} com o dia de referência fixado
350	 * em "mesmo dia da semana passada" (nome da v1/v2 — mantido para não quebrar
351	 * a API existente).
352	 */
353	export function proRataLastWeekBase(
354	  lastWeek: number | null | undefined,
355	  now: Date,
356	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
357	): number | null {
358	  return proRataDayBase(lastWeek, now, hours);
359	}
