482	/**
483	 * Exceção "sem movimentação" derivada DIRETO do dado estruturado (timestamp
484	 * da última bipagem + janela), nunca por parsing de string de ragReasons —
485	 * por isso INDEPENDE da cor do card (aparece mesmo com card vermelho) e
486	 * cobre também a fábrica (janela/threshold próprios via parâmetros).
487	 * Retorna null quando não há gap acima do threshold dentro da janela.
488	 */
489	export function buildNoMovementException(
490	  input: NoMovementExceptionInput,
491	): TvException | null {
492	  const threshold = input.thresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
493	  const gap = hoursWithoutMovementInWindow(
494	    input.lastMovementAt,
495	    input.now,
496	    input.hours ?? TV_BUSINESS_HOURS,
497	  );
498	  if (gap === null || gap <= threshold) return null;
499	  return {
500	    id: `no-movement:${input.lojaId}`,
501	    kind: 'no-movement',
502	    severity: 'amber',
503	    lojaId: input.lojaId,
504	    lojaNome: input.lojaNome,
505	    message: `${input.lojaNome} sem movimentação há ${Math.floor(gap)}h em horário comercial`,
506	  };
507	}
