539	// ─────────────────────────────────────────────────────────────────────────────
540	// Staleness
541	// ─────────────────────────────────────────────────────────────────────────────
542	
543	/**
544	 * Classifica o frescor de um dado-fonte dado o intervalo esperado:
545	 * - `fresh`: idade abaixo de 2× o intervalo esperado (tolera um ciclo perdido).
546	 * - `stale`: idade entre 2× e 6× (âmbar na UI, conforme spec).
547	 * - `very-stale`: idade a partir de 6×, timestamp inválido ou ausente.
548	 */
549	export function classifyStaleness(
550	  lastUpdatedAt: Date | string | number | null | undefined,
551	  expectedIntervalMs: number,
552	  now: Date,
553	): TvFreshnessLevel {
554	  if (lastUpdatedAt == null) return 'very-stale';
555	  const ts = new Date(lastUpdatedAt).getTime();
556	  if (!Number.isFinite(ts) || ts <= 0) return 'very-stale';
557	  const age = now.getTime() - ts;
558	  if (age < 2 * expectedIntervalMs) return 'fresh';
559	  if (age < 6 * expectedIntervalMs) return 'stale';
560	  return 'very-stale';
561	}
562	
563	/**
564	 * Monta o freshness consolidado a partir dos timestamps CRUS de última
565	 * atualização bem-sucedida (React Query `dataUpdatedAt`, em ms; 0 = nunca).
566	 *
567	 * A classificação depende de `now`: o chamador DEVE reavaliar com um relógio
568	 * que AVANÇA (tick de minuto), para que um outage total — nenhuma query
569	 * devolvendo dado novo — escale o chip pra âmbar quando `dataUpdatedAt`
570	 * parar de avançar além de 2× o intervalo esperado.
571	 */
572	export function buildFreshness(
573	  liveUpdatedAtMs: number,
574	  stockUpdatedAtMs: number,
575	  intervals: { liveMs: number; slowMs: number },
576	  now: Date,
577	): TvFreshness {
578	  const liveUpdatedAt =
579	    liveUpdatedAtMs > 0 ? new Date(liveUpdatedAtMs).toISOString() : null;
580	  const stockUpdatedAt =
581	    stockUpdatedAtMs > 0 ? new Date(stockUpdatedAtMs).toISOString() : null;
582	  return {
583	    vendasLive: {
584	      updatedAt: liveUpdatedAt,
585	      level: classifyStaleness(liveUpdatedAt, intervals.liveMs, now),
586	      expectedIntervalMs: intervals.liveMs,
587	    },
588	    estoque: {
589	      updatedAt: stockUpdatedAt,
590	      level: classifyStaleness(stockUpdatedAt, intervals.slowMs, now),
591	      expectedIntervalMs: intervals.slowMs,
592	    },
593	    geradoEm: now.toISOString(),
594	  };
595	}
