695	 * true quando o setor é o {@link TV_ALERT_SETOR} (igualdade EXATA após
696	 * {@link normalizeSetor} — nunca prefixo: "PRODUTOS DE LIMPEZA" NÃO conta).
697	 */
698	export function isTvAlertSetor(setor: string | null | undefined): boolean {
699	  return normalizeSetor(setor) === normalizeSetor(TV_ALERT_SETOR);
