974	// ─────────────────────────────────────────────────────────────────────────────
975	// Paginação PostgREST (loop genérico com fetcher injetado — sem I/O próprio)
976	// ─────────────────────────────────────────────────────────────────────────────
977	
978	/** Página de resultado mínima consumida por {@link fetchAllPages}. */
979	export interface TvPageResult<T> {
980	  data: T[] | null;
981	  error: { message: string } | null;
982	}
983	
984	/**
985	 * Busca TODAS as linhas paginando com `.range()`: o PostgREST corta qualquer
986	 * resposta em 1000 linhas mesmo com `.limit()` maior — truncamento SILENCIOSO
987	 * (mesmo padrão de `features/producao/hooks/useProductionForecast`).
988	 *
989	 * Loop até a página vir menor que `pageSize`. O fetcher é injetado (esta
990	 * função não faz I/O próprio — testável com mock) e DEVE aplicar ordenação
991	 * estável (`.order` em coluna única, ex.: `id`) para as páginas não se
992	 * sobreporem entre requests.
993	 */
994	export async function fetchAllPages<T>(
995	  fetchPage: (from: number, to: number) => PromiseLike<TvPageResult<T>>,
996	  pageSize = 1000,
997	): Promise<T[]> {
998	  const all: T[] = [];
999	  let offset = 0;
1000	  for (;;) {
1001	    const { data, error } = await fetchPage(offset, offset + pageSize - 1);
1002	    if (error) throw error;
1003	    const rows = data ?? [];
1004	    all.push(...rows);
1005	    if (rows.length < pageSize) return all;
1006	    offset += pageSize;
1007	  }
1008	}
