/* §8.1.1-ext — flash dourado ao atualizar número de venda (400ms, cor only) */
@media (prefers-reduced-motion: no-preference) {
  @keyframes tv-value-flash {
    0% {
      color: inherit;
    }
    20% {
      color: #c5a065;
    }
    100% {
      color: inherit;
    }
  }

  .tv-value-flash {
    animation: tv-value-flash 400ms ease-out both;
  }
}

/* §7-ext — skeleton shimmer para colunas em loading */
@keyframes tv-skeleton-shimmer {
  0% {
    background-position: -400px 0;
  }
  100% {
    background-position: 400px 0;
  }
}

@media (prefers-reduced-motion: no-preference) {
  .tv-skeleton-shimmer > * {
    background: linear-gradient(
      90deg,
      transparent 0%,
      rgba(87, 113, 91, 0.06) 50%,
      transparent 100%
    );
    background-size: 400px 100%;
    animation: tv-skeleton-shimmer 1.4s ease-in-out infinite;
  }
}

/* §8.1.2-ext — stagger de entrada das colunas (transform/opacity only) */
@media (prefers-reduced-motion: no-preference) {
  .tv-col-enter {
    animation: tv-content-enter 300ms ease-out both;
  }

  .tv-col-enter-1 {
    animation-delay: 0ms;
  }

  .tv-col-enter-2 {
    animation-delay: 60ms;
  }

  .tv-col-enter-3 {
    animation-delay: 120ms;
  }

  .tv-col-enter-4 {
    animation-delay: 180ms;
  }

  .tv-col-enter-5 {
    animation-delay: 240ms;
  }

  .tv-col-enter-6 {
    animation-delay: 300ms;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tv-pixel-shift,
  .tv-fade-in,
  .tv-content-enter,
  .tv-dot,
  .tv-value-flash,
  .tv-col-enter {
    animation: none;
  }
}

