   transição são aplicadas via Tailwind nos componentes; aqui apenas as
   desligamos sob reduced-motion (ver bloco prefers-reduced-motion:reduce abaixo). */

/* §8.1.1-ext — flash dourado ao atualizar número de venda (400ms, cor only) */

// ─────────────────────────────────────────────────────────────────────────────
// Chip de ranking (1ª / 2ª / 3ª loja por venda) — apenas period "today"
// ─────────────────────────────────────────────────────────────────────────────

interface TvRankChipProps {
  /** Posição de 1 a 3 (valores maiores não geram chip). */
  rank: 1 | 2 | 3;
}

/**
 * Badge compacto de ranking da loja por venda do dia (top-3).
 * Dourado para 1ª; sage suave para 2ª e 3ª (hierarquia visual sem excesso).
 */
export function TvRankChip({ rank }: TvRankChipProps) {
  const isGold = rank === 1;
  const label = rank === 1 ? '🥇 1ª' : rank === 2 ? '2ª' : '3ª';
  return (
    <span
      className={`inline-flex items-center rounded-full px-2.5 py-0.5 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] font-semibold leading-none tabular-nums ${
        isGold
          ? 'bg-[#C5A065]/10 text-[#C5A065]'
          : 'bg-[#57715B]/8 text-[#7C887E]'
      }`}
      data-testid={`tv-rank-chip-${rank}`}
      aria-label={`${rank}ª colocada`}
    >
      {label}
    </span>
  );
}

