/**
 * Barra de meta FINA por coluna de loja: lógica idêntica ao hero, visual mais
 * compacto (h-1.5 lg:h-2) com label "XX% · esperado YY%" ao lado.
 */
export function TvColumnMetaBar({
  pctMetaProRata,
  metaDia,
  now,
}: {
  /** % pró-rata da meta do dia (pode ser null quando sem meta ou fora da janela). */
  pctMetaProRata: number | null;
  /** Meta do dia em R$ (null = sem meta cadastrada). */
  metaDia: number | null;
  now: Date;
}) {
  if (metaDia == null || metaDia <= 0) {
    return (
      <p className="mt-1 font-momma text-[clamp(0.6125rem,0.7vw,1.25rem)] text-[#7C887E]">
        sem meta
      </p>
    );
  }

  const fillPct = pctMetaProRata;
  const expectedPct = expectedPctNow(now);
  const ratio =
    fillPct != null && expectedPct > 0 ? fillPct / expectedPct : null;
  const color = metaBarColorFromRatio(ratio, now);

  return (
    <div className="mt-1.5 flex items-center gap-2" data-testid="tv-col-meta-bar">
      <div className="relative flex-1 rounded-full bg-[#57715B]/10 h-1.5 lg:h-2">
        {fillPct != null && (
          <div
            className={`absolute inset-y-0 left-0 rounded-full transition-[width] [transition-duration:600ms] ease-out motion-reduce:transition-none ${
              color === 'sage'
                ? 'bg-gradient-to-r from-[#57715B] to-[#4a6250]'
                : color === 'amber'
                  ? 'bg-gradient-to-r from-amber-400 to-amber-500'
                  : 'bg-gradient-to-r from-red-400 to-red-500'
            }`}
            style={{ width: `${Math.max(0, Math.min(100, fillPct))}%` }}
          />
        )}
        {expectedPct > 0 && (
          <div
            className="absolute rounded-full bg-[#C5A065]"
            style={{
              left: `calc(${Math.max(0, Math.min(100, expectedPct))}% - 1px)`,
              top: -3,
              width: 2,
              height: 14,
            }}
          />
        )}
      </div>
      <p className="shrink-0 font-momma text-[clamp(0.6125rem,0.7vw,1.25rem)] tabular-nums text-[#7C887E]">
        {fillPct != null ? `${Math.round(fillPct)}%` : '—'}
        {' · esp. '}
        {expectedPct}%
      </p>
    </div>
  );
}

