/**
 * @module features/tv-dashboard/ui/TvStoreColumn
 *
 * Coluna VERTICAL de loja da v3 (substitui o card horizontal da v2).
 * De cima para baixo: header (nome + chip RAG + fonte + ranking) · última
 * bipagem · vendas de hoje + % vs ontem (pró-rata p/ canal live; Linx com
 * selo honesto "até DD/MM") · barra de meta fina · ticket médio + cupons
 * (live) · perdas do período do filtro global · estoque crítico NOMEADO
 * (top 5) · mini-feed "AGORA". A coluna inteira é clicável e navega para
 * `/tv/loja/:id`.
 */

import { useEffect, useRef, useState } from 'react';
import type { TvFreshnessLevel, TvPeriod, TvStoreData } from '../model/types';
import { formatCompactBRL, parseBrDateTime, parseIsoDateLocal } from '../model/tvMath';
import { TvDeltaChip, TvRankChip, TvSourceChip, TvStateChip } from './TvChips';
import {
  TvColumnBipLine,
  TvColumnCritical,
  TvColumnFeed,
  TvColumnMetaBar,
  TvColumnPerdas,
  TvUnitColumn,
} from './TvColumnParts';
import { formatTicketBRL, formatTimeHHMM, formatWeekdayDayMonth } from './tvFormat';
import { useCountUp } from './useCountUp';

interface TvStoreColumnProps {
  store: TvStoreData;
  /** Freshness da fonte de vendas live (chip "ao vivo"/"atrasado"). */
  liveLevel: TvFreshnessLevel;
  /** Período do filtro global (rótulo honesto das perdas). */
  period: TvPeriod;
  now: Date;
  /** Posição no ranking de vendas do dia (1–3), ou null fora do top-3. */
  rank?: number | null;
}

/** Coluna de loja: cobre canal Degust live e Linx defasado. */
export function TvStoreColumn({ store, liveLevel, period, now, rank }: TvStoreColumnProps) {
  const { vendas, channel } = store;
  const isLive = channel === 'degust-live';
  const valorAnim = useCountUp(vendas?.valor ?? 0);
  const refDate = vendas ? parseIsoDateLocal(vendas.dataReferencia) : null;

  // Flash dourado ao atualizar o valor de venda
  const prevValueRef = useRef(vendas?.valor);
  const [flashing, setFlashing] = useState(false);
  const flashKeyRef = useRef(0);
  useEffect(() => {
    if (
      vendas?.valor != null &&
      prevValueRef.current != null &&
      vendas.valor !== prevValueRef.current
    ) {
      flashKeyRef.current += 1;
      setFlashing(true);
      const t = window.setTimeout(() => setFlashing(false), 450);
      prevValueRef.current = vendas.valor;
      return () => window.clearTimeout(t);
    }
    prevValueRef.current = vendas?.valor;
  }, [vendas?.valor]);

  // Caption sob as vendas: honestidade da fonte (live × defasado × sem dado)
  let caption: string;
  if (vendas == null) {
    caption = 'sem dado de venda disponível';
  } else if (isLive) {
    // `ultima_atualizacao` do Degust vem "DD/MM/YYYY HH:mm:ss" — parser
    // dedicado pt-BR (new Date() falha para dia > 12).
    const upd = formatTimeHHMM(parseBrDateTime(vendas.atualizadoEm));
    caption = `hoje${upd ? ` · atualizado ${upd}` : ''}`;
  } else {
    caption = `${refDate ? formatWeekdayDayMonth(refDate) : ''} — último dia com dados`;
  }

  const showRank = rank != null && rank >= 1 && rank <= 3 && period === 'today';

  return (
    <TvUnitColumn
      lojaId={store.lojaId}
      nome={store.nome}
      rag={store.rag}
      testId="tv-store-column"
    >
      {/* Header: nome + chips (RAG + fonte + ranking) */}
      <div className="flex flex-wrap items-center justify-between gap-x-2 gap-y-1">
        <h2 className="min-w-0 truncate font-momma text-[clamp(0.9375rem,1.05vw,1.875rem)] font-semibold leading-tight text-[#2D362E]">
          {store.nome}
        </h2>
        <div className="flex shrink-0 flex-wrap items-center justify-end gap-1.5">
          {showRank && <TvRankChip rank={rank as 1 | 2 | 3} />}
          <TvStateChip rag={store.rag} />
          <TvSourceChip
            channel={channel}
            liveLevel={liveLevel}
            laggedDate={vendas?.dataReferencia ?? null}
          />
        </div>
      </div>
      <TvColumnBipLine ultimaBipagem={store.movimentacao.ultimaBipagem} now={now} />

      {/* Vendas de hoje + % vs ontem (principal v3) */}
      <div className="mt-2 flex flex-wrap items-end gap-x-2 gap-y-1">
        <span
          key={flashing ? `flash-${flashKeyRef.current}` : 'static'}
          className={`font-momma text-[clamp(1.75rem,2.4vw,4.5rem)] font-bold leading-none tabular-nums ${
            vendas ? 'text-[#2D362E]' : 'text-[#7C887E]'
          }${flashing ? ' tv-value-flash' : ''}`}
          data-testid="tv-store-sales"
        >
          {vendas ? formatCompactBRL(valorAnim) : '—'}
        </span>
        {store.deltaOntem != null && (
          <TvDeltaChip
            delta={store.deltaOntem}
            label={isLive ? 'ontem' : 'dia ant.'}
            size="card"
          />
        )}
      </div>

      {/* Dot de caixa aberto/fechado + caption */}
      <p className="mt-1 flex items-center font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] font-medium leading-tight text-[#7C887E]">
        {isLive && vendas?.caixaAberto != null && (
          <span
            className={`mr-1.5 inline-block h-2 w-2 shrink-0 rounded-full ${
              vendas.caixaAberto ? 'bg-emerald-400' : 'bg-[#7C887E]'
            }`}
            aria-label={vendas.caixaAberto ? 'caixa aberto' : 'caixa fechado'}
          />
        )}
        {caption}
      </p>

      {/* Barra de meta fina por coluna */}
      <TvColumnMetaBar pctMetaProRata={store.pctMeta} metaDia={store.metaDia} now={now} />

      {/* Ticket médio + cupons (apenas live com dado disponível) */}
      {isLive && vendas?.ticketMedio != null && vendas.ticketMedio > 0 && (
        <p className="mt-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] font-medium leading-tight text-[#7C887E] tabular-nums">
          TM {formatTicketBRL(vendas.ticketMedio)}
          {vendas.cupons != null && ` · ${vendas.cupons} cupons`}
        </p>
      )}

      <TvColumnPerdas perdas={store.perdas} period={period} />
      <TvColumnCritical items={store.criticalItems} />
      <TvColumnFeed moves={store.recentMoves} />
    </TvUnitColumn>
  );
}

/**
 * @module features/tv-dashboard/ui/TvDashboard.page
 *
 * Página `/tv` — Torre de Controle da Operação (spec v3). Renderiza
 * FORA do DashboardLayout (sem sidebar), em LIGHT hardcoded (independe do
 * toggle de tema): glassmorphism Momma sobre fundo branco com ambiência da
 * marca (awning, folhas, glows). Layout FLUIDO mobile-first: empilha com
 * scroll natural em telas pequenas e trava na viewport (zero scroll) em
 * TV/monitor grande via `.tv-lock-*` (tv.css).
 *
 * v3: hero com filtro global Hoje/Semana/Mês + 6 COLUNAS VERTICAIS
 * clicáveis (1 por unidade, fábrica na posição 6) que navegam para o
 * drill-down `/tv/loja/:id`. A faixa inferior de exceções/top-produtos da
 * v2 saiu — o conteúdo vive nas colunas e no drill-down.
 */

import { useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Leaf, Settings2 } from 'lucide-react';
import type { TvPeriod } from '../model/types';
import { useTvDashboardData } from '../model/useTvDashboardData';
import { useTvRealtime } from '../model/useTvRealtime';
import { TvHero } from './TvHero';
import { TvStoreColumn } from './TvStoreColumn';
import { TvFabricaColumn } from './TvFabricaColumn';
import { useMinuteClock } from '../model/useMinuteClock';
import './tv.css';

/** Tempo que o botão Metas permanece visível após mousemove (§8.4). */
const METAS_BUTTON_VISIBLE_MS = 5_000;

/**
 * Ambiência Momma replicada do `MommaPageLayout` (que não cabe no chassi
 * fullscreen da TV): awning stripe verde no topo, folhas decorativas
 * ESTÁTICAS (sem `animate-pulse` — §8.2 proíbe animação contínua) e
 * ambient glows verde/dourado.
 */
function TvAmbience() {
  return (
    <div className="pointer-events-none absolute inset-0 overflow-hidden" aria-hidden>
      {/* Awning stripe (toldo da marca) */}
      <div className="absolute left-0 right-0 top-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80" />
      {/* Folhas decorativas estáticas */}
      <div className="absolute right-[-10%] top-[-5%] h-[300px] w-[300px] opacity-[0.03]">
        <Leaf className="h-full w-full rotate-12 text-[#57715B]" />
      </div>
      <div className="absolute bottom-[-10%] left-[-15%] h-[400px] w-[400px] opacity-[0.03]">
        <Leaf className="h-full w-full -rotate-45 text-[#57715B]" />
      </div>
      {/* Ambient glows */}
      <div className="absolute left-[10%] top-[20%] h-[200px] w-[200px] rounded-full bg-[#57715B]/5 blur-[80px]" />
      <div className="absolute bottom-[30%] right-[10%] h-[250px] w-[250px] rounded-full bg-[#C5A065]/5 blur-[80px]" />
    </div>
  );
}

/** Card-chassi anônimo do estado de erro total (design.md §7). */
function TvErrorCard() {
  return (
    <section className="relative flex flex-col overflow-hidden rounded-[2rem] border border-[#57715B]/10 bg-white/60 p-4 shadow-[0_8px_32px_rgba(0,0,0,0.06)] backdrop-blur-xl saturate-150 lg:p-5">
      <div
        className="pointer-events-none absolute inset-0 bg-gradient-to-br from-white/40 via-transparent to-[#C5A065]/5"
        aria-hidden
      />
      <div className="relative z-10 flex h-full flex-col">
        <div className="flex items-center justify-between gap-3">
          <span className="font-momma text-[clamp(1rem,1.45vw,2.625rem)] font-semibold text-[#7C887E]">
            —
          </span>
          <span className="inline-flex items-center rounded-full border border-amber-400/40 bg-amber-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium text-amber-600">
            sem conexão
          </span>
        </div>
        <span className="mt-4 font-momma text-[clamp(2rem,3.35vw,6rem)] font-bold leading-none text-[#7C887E]">
          —
        </span>
      </div>
    </section>
  );
}

/** Skeleton de uma coluna no estado de loading inicial. */
function TvColumnSkeleton({ delay = 0 }: { delay?: number }) {
  return (
    <div
      className="relative overflow-hidden rounded-[2rem] bg-white/60 p-3.5 backdrop-blur-xl saturate-150 border border-[#57715B]/10"
      style={{ animationDelay: `${delay}ms` }}
    >
      <div className="tv-skeleton-shimmer space-y-3">
        <div className="h-4 w-2/3 rounded-full bg-[#57715B]/8" />
        <div className="h-10 w-3/4 rounded-full bg-[#57715B]/8" />
        <div className="h-2 w-full rounded-full bg-[#57715B]/8" />
        <div className="h-3 w-1/2 rounded-full bg-[#57715B]/8" />
        <div className="mt-4 space-y-2">
          <div className="h-3 w-full rounded bg-[#57715B]/6" />
          <div className="h-3 w-4/5 rounded bg-[#57715B]/6" />
          <div className="h-3 w-3/5 rounded bg-[#57715B]/6" />
        </div>
      </div>
    </div>
  );
}

/** Skeleton do hero durante loading. */
function TvHeroSkeleton() {
  return (
    <div className="relative overflow-hidden rounded-[2rem] bg-white/60 p-4 backdrop-blur-xl saturate-150 border border-[#57715B]/10 lg:p-5">
      <div className="tv-skeleton-shimmer flex items-center gap-6">
        <div className="h-16 w-48 rounded-full bg-[#57715B]/8" />
        <div className="flex-1 space-y-2">
          <div className="h-4 w-1/3 rounded-full bg-[#57715B]/8" />
          <div className="h-3 w-full rounded-full bg-[#57715B]/8" />
        </div>
      </div>
    </div>
  );
}

/**
 * Stagger delay CSS classes por índice de coluna (1-based).
 * Reutiliza a animação `tv-content-enter` com delay escalonado.
 */
const COL_ENTER_CLS = [
  'tv-col-enter tv-col-enter-1',
  'tv-col-enter tv-col-enter-2',
  'tv-col-enter tv-col-enter-3',
  'tv-col-enter tv-col-enter-4',
  'tv-col-enter tv-col-enter-5',
  'tv-col-enter tv-col-enter-6',
] as const;

/** Página raiz do painel TV. */
export default function TvDashboardPage() {
  const navigate = useNavigate();
  // Filtro global v3: muda perdas/compras/comparativos (vendas seguem hoje)
  const [period, setPeriod] = useState<TvPeriod>('today');
  const data = useTvDashboardData(period);
  useTvRealtime();
  const now = useMinuteClock();

  // Telas touch (sem hover) não disparam mousemove confiável — o botão
  // Metas fica SEMPRE visível, discreto no canto (design.md §8.4).
  const [isTouch] = useState(
    () =>
      typeof window !== 'undefined' &&
      typeof window.matchMedia === 'function' &&
      window.matchMedia('(hover: none)').matches,
  );

  // Botão fantasma "Metas": invisível por padrão; mousemove revela por 5s
  // e suspende o cursor-none enquanto visível (design.md §8.4).
  const [controlsVisible, setControlsVisible] = useState(false);
  const hideTimer = useRef<number | null>(null);
  useEffect(() => {
    const onMove = () => {
      setControlsVisible(true);
      if (hideTimer.current != null) window.clearTimeout(hideTimer.current);
      hideTimer.current = window.setTimeout(
        () => setControlsVisible(false),
        METAS_BUTTON_VISIBLE_MS,
      );
    };
    window.addEventListener('mousemove', onMove);
    return () => {
      window.removeEventListener('mousemove', onMove);
      if (hideTimer.current != null) window.clearTimeout(hideTimer.current);
    };
  }, []);

  // Ranking das lojas por venda do dia (apenas period "today"; baseado no valor raw)
  const rankedStores = useMemo(() => {
    if (!data.stores) return [] as typeof data.stores;
    return data.stores.map((s, _, arr) => {
      const vendas = s.vendas?.valor ?? 0;
      const rank = vendas > 0
        ? arr.filter((x) => (x.vendas?.valor ?? 0) > vendas).length + 1
        : null;
      return { ...s, rank };
    });
  }, [data.stores]);

  // ── Loading inicial: skeleton de hero + 6 colunas ──
  if (data.isLoading) {
    return (
      <div className="relative min-h-dvh select-none bg-white font-momma antialiased">
        <TvAmbience />
        <div className="relative flex flex-col gap-4 p-4 sm:p-6 lg:gap-5 lg:px-8 lg:py-6">
          <TvHeroSkeleton />
          <div className="grid auto-rows-fr grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 lg:gap-5 xl:grid-cols-6 xl:gap-4">
            {Array.from({ length: 6 }, (_, i) => (
              <TvColumnSkeleton key={i} delay={i * 60} />
            ))}
          </div>
        </div>
      </div>
    );
  }

  const storeCards = rankedStores.slice(0, data.factory ? 5 : 6);

  // Em touch o botão Metas é permanente; com mouse, segue o ghost de 5s.
  const metasVisible = isTouch || controlsVisible;

  return (
    <div
      className={`tv-lock-viewport relative min-h-dvh select-none overflow-x-hidden bg-white font-momma text-[#2D362E] antialiased ${
        metasVisible ? '' : 'cursor-none'
      }`}
      data-testid="tv-dashboard"
    >
      <TvAmbience />

      <div className="tv-pixel-shift tv-lock-fill relative">
        <div className="tv-content-enter tv-lock-fill flex flex-col gap-4 p-4 sm:p-6 lg:gap-5 lg:px-8 lg:py-6">
          {/* Linha 1 — hero (com filtro global Hoje/Semana/Mês) */}
          <TvHero
            network={data.network}
            freshness={data.freshness}
            now={now}
            period={period}
            onPeriodChange={setPeriod}
          />

          {/* Linha 2 — colunas verticais de unidade (fábrica na posição 6):
              1 col no mobile → 2 (sm) → 3 (lg) → 6 lado a lado em xl+/TV;
              no viewport-lock absorvem a altura restante (tv-lock-grow). */}
          <div className="tv-lock-grow grid auto-rows-fr grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 lg:gap-5 xl:grid-cols-6 xl:gap-4">
            {data.isError ? (
              <>
                {Array.from({ length: 6 }, (_, i) => (
                  <TvErrorCard key={i} />
                ))}
              </>
            ) : (
              <>
                {storeCards.map((store, idx) => (
                  <div key={store.lojaId} className={COL_ENTER_CLS[idx] ?? 'tv-col-enter tv-col-enter-1'}>
                    <TvStoreColumn
                      store={store}
                      liveLevel={data.freshness.vendasLive.level}
                      period={period}
                      now={now}
                      rank={store.rank}
                    />
                  </div>
                ))}
                {data.factory && (
                  <div className={COL_ENTER_CLS[storeCards.length] ?? 'tv-col-enter tv-col-enter-6'}>
                    <TvFabricaColumn
                      factory={data.factory}
                      freshness={data.freshness}
                      period={period}
                      now={now}
                    />
                  </div>
                )}
              </>
            )}
          </div>
        </div>
      </div>

      {/* Botão de Metas (§8.4): fantasma com mouse, permanente em touch */}
      <button
        type="button"
        onClick={() => navigate('/tv/metas')}
        data-mia-action="abrir-metas-painel-tv"
        className={`fixed bottom-4 right-4 flex h-11 items-center gap-2 rounded-full border border-[#57715B]/15 bg-white/80 px-5 font-momma text-[clamp(0.875rem,1.05vw,1.25rem)] font-medium text-[#57715B] shadow-[0_4px_16px_rgba(0,0,0,0.08)] backdrop-blur-md transition-opacity duration-200 motion-reduce:transition-none lg:bottom-6 lg:right-8 ${
          metasVisible ? 'opacity-100' : 'pointer-events-none opacity-0'
        }`}
        aria-hidden={!metasVisible}
        tabIndex={metasVisible ? 0 : -1}
      >
        <Settings2 className="h-5 w-5" aria-hidden />
        Metas
      </button>
    </div>
  );
}

